draw:
var R = p.radius, lam = p.lambda * 1e-9, ng = p.ngap;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var mMax = 14;
var rMax = Math.sqrt(mMax * lam * R / ng);
var cx = W * 0.5, cy = H * 0.52;
var Rpx = Math.min(W, H) * 0.42;
var S = Rpx / rMax;

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, Rpx, 0, Math.PI * 2); ctx.stroke();

var highlight = 1 + (Math.floor(t / 1.2) % 6);

for (var m = 1; m <= mMax; m++) {
  var r = Math.sqrt(m * lam * R / ng) * S;
  if (r > Rpx) break;
  ctx.strokeStyle = (m === highlight) ? C.accent : C.ink;
  ctx.lineWidth = (m === highlight) ? 3 : 1.6;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillText("dark centre, m = 0", cx, cy + Rpx + 18);

var rh = Math.sqrt(highlight * lam * R / ng);
var rhpx = rh * S;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + rhpx, cy); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("m = " + highlight, cx + rhpx * 0.35, cy - 6);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("dark rings, 2 n t = m lambda", 6, 14);

out.note = "ring m = " + highlight + " has radius " + (rh * 1000).toFixed(3) +
  " mm  |  gap there t = " + (rh * rh / (2 * R) * 1e9).toFixed(0) + " nm";
